function f(o){const n=o.length;if(n===0)return[];let e=[];e.push({...o[0]});for(let t=0;t<n-1;t++){const u=o[t],r=o[t+1];e.push({x:u.x*.75+r.x*.25,y:u.y*.75+r.y*.25},{x:u.x*.25+r.x*.75,y:u.y*.25+r.y*.75})}return n>1&&e.push({...o[n-1]}),e}function p(o,n=.25){const e=o.length;if(e===0)return[];let t=[],u=1-n,r=n;t.push([...o[0]]);for(let l=0;l<e-1;l++){const c=o[l],h=o[l+1];t.push([c[0]*u+h[0]*r,c[1]*u+h[1]*r],[c[0]*r+h[0]*u,c[1]*r+h[1]*u])}return e>1&&t.push([...o[e-1]]),t}function s(o,n){let e=o;for(let t=0;t<n;t++)e=f(e);return e}function x(o,n,e=.25){let t=o;for(let u=0;u<n;u++)t=p(t,e);return t}export{x as a,s as c};
